use bcrypt::{hash, verify, DEFAULT_COST};
use std::io;

/// Hashes a plain text password using bcrypt.
///
/// # Arguments
///
/// * `password` - A string slice that holds the plain text password to be hashed.
///
/// # Returns
///
/// * `Ok(String)` containing the hashed password on success.
/// * `Err(io::Error)` if an error occurs during hashing.
pub fn hash_password(password: &str) -> io::Result<String> {
    let salt = bcrypt::gen_salt(DEFAULT_COST)?;
    hash(password, &salt)
}

/// Verifies a plain text password against a hashed password.
///
/// # Arguments
///
/// * `plain_password` - A string slice that holds the plain text password to be verified.
/// * `hashed_password` - A string slice that holds the hashed password for comparison.
///
/// # Returns
///
/// * `Ok(bool)` indicating whether the passwords match (`true`) or not (`false`).
/// * `Err(io::Error)` if an error occurs during verification.
pub fn verify_password(plain_password: &str, hashed_password: &str) -> io::Result<bool> {
    verify(plain_password, hashed_password)
}

