use serde::{Deserialize, Serialize};
use jsonwebtoken::{encode, decode, Header, EncodingKey, DecodingKey, Validation};
use std::time::{SystemTime, Duration};

#[derive(Debug, Serialize, Deserialize)]
struct Claims {
    sub: String,
    exp: usize,
}

pub struct SessionManager {
    secret_key: String,
}

impl SessionManager {
    pub fn new(secret_key: &str) -> Self {
        SessionManager {
            secret_key: secret_key.to_string(),
        }
    }

    // Generate a token for a user
    pub fn generate_token(&self, user_id: &str) -> Result<String, jsonwebtoken::errors::Error> {
        let header = Header::default();
        let claims = Claims {
            sub: user_id.to_string(),
            exp: (SystemTime::now() + Duration::from_secs(3600)).duration_since(SystemTime::UNIX_EPOCH)?.as_secs() as usize,
        };
        encode(&header, &claims, &EncodingKey::from_secret(self.secret_key.as_bytes()))
    }

    // Validate a token and return the user_id
    pub fn validate_token(&self, token: &str) -> Result<String, jsonwebtoken::errors::Error> {
        let token_data = decode::<Claims>(
            token,
            &DecodingKey::from_secret(self.secret_key.as_bytes()),
            &Validation::default(),
        )?;
        Ok(token_data.claims.sub)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_generate_and_validate_token() {
        let session_manager = SessionManager::new("secret");
        let user_id = "user123";
        match session_manager.generate_token(user_id) {
            Ok(token) => {
                match session_manager.validate_token(&token) {
                    Ok(decoded_user_id) => assert_eq!(decoded_user_id, user_id),
                    Err(e) => panic!("Failed to validate token: {}", e),
                }
            },
            Err(e) => panic!("Failed to generate token: {}", e),
        }
    }
}


### Explanation:

1. **Structs**:
   - `Claims`: This struct holds the payload of the JWT (JSON Web Token). It includes a subject (`sub`) and an expiration time (`exp`).

2. **SessionManager**:
   - `new`: Initializes a new instance of `SessionManager` with a secret key.
   - `generate_token`: Generates a JWT for a given user ID. The token is valid for 1 hour.
   - `validate_token`: Validates a JWT and returns the user ID if the token is valid.

3. **Testing**:
   - A test case is provided to ensure that the token generation and validation work as expected.

### Notes:

- **Security**: The secret key should be kept secure and not hard-coded in your source code, especially in production environments.
- **Token Expiry**: You can adjust the expiration time based on your requirements.
- **Error Handling**: Proper error handling is crucial for robustness. Adjust error handling as needed based on your application's requirements.

