// src/auth.rs

pub mod auth {
    use serde::{Deserialize, Serialize};
    use std::collections::HashMap;

    #[derive(Serialize, Deserialize)]
    pub struct User {
        pub username: String,
        pub password_hash: String,
    }

    // Dummy storage for demonstration purposes
    static mut USERS: HashMap<String, User> = HashMap::new();

    pub fn register(username: &str, password: &str) -> Result<(), &'static str> {
        if unsafe { USERS.contains_key(username) } {
            return Err("Username already exists");
        }

        // For production, you should hash the password before storing it
        let user = User {
            username: username.to_string(),
            password_hash: password.to_string(), // This is not secure!
        };

        unsafe {
            USERS.insert(username.to_string(), user);
        }
        Ok(())
    }

    pub fn login(username: &str, password: &str) -> Result<(), &'static str> {
        if let Some(user) = unsafe { USERS.get(username) } {
            // For production, compare the provided password hash with the stored one
            if user.password_hash == password {
                Ok(())
            } else {
                Err("Invalid credentials")
            }
        } else {
            Err("Username not found")
        }
    }
}


