use super::auth;

#[derive(serde::Deserialize)]
struct RegisterRequest {
    username: String,
    password: String,
}

#[derive(serde::Deserialize)]
struct LoginRequest {
    username: String,
    password: String,
}

#[actix_web::get("/register")]
async fn register(user_data: web::Json<RegisterRequest>) -> impl Responder {
    match auth::register(&user_data.username, &user_data.password) {
        Ok(_) => HttpResponse::Ok().body("User registered successfully"),
        Err(e) => HttpResponse::BadRequest().body(e),
    }
}

#[actix_web::post("/login")]
async fn login(user_data: web::Json<LoginRequest>) -> impl Responder {
    match auth::login(&user_data.username, &user_data.password) {
        Ok(_) => HttpResponse::Ok().body("Login successful"),
        Err(e) => HttpResponse::Unauthorized().body(e),
    }
}


